function loadState() { try { const stored = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'); const files = Array.isArray(stored.files) ? stored.files.map(file => ({ ...file, history: Array.isArray(file.history) && file.history.length ? file.history : [{ version: Number(file.version || 1), prompt: file.prompt || '', workbook: file.workbook, createdAt: new Date().toISOString() }] })) : []; return { ...defaults, ...stored, files, view: 'marketing', sessionId: '', authUser: null, generating: false, modal: null, menu: false }; } catch { return { ...defaults }; } }
function save() { localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...state, menu: false, modal: null, generating: false })); }
function t(key) { return copy[state.lang][key] || key; }
function esc(value) { return String(value).replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#039;' }[c])); }

function authHeaders(accessToken = authSession()?.access_token) { return accessToken ? { authorization: `Bearer ${accessToken}` } : {}; }
function authSession() { try { return JSON.parse(localStorage.getItem(AUTH_STORAGE_KEY) || 'null'); } catch { return null; } }
function normalizeAuthSession(session) { return session?.access_token ? { ...session, expires_at: session.expires_at || Math.floor(Date.now() / 1000) + Number(session.expires_in || 3600) } : session; }
function storeAuthSession(session) { if (session?.access_token) localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(session)); }
function clearAuthSession() { localStorage.removeItem(AUTH_STORAGE_KEY); }
function trackMeta(event, data = {}, custom = false) {
  if (typeof window.fbq !== 'function') return;
  try { window.fbq(custom ? 'trackCustom' : 'track', event, data); } catch { /* Marketing telemetry must never affect the app. */ }
}
function pixelPlanValue(plan, billing = 'monthly') {
  const prices = { starter: { monthly: 4900, annual: 46900 }, pro: { monthly: 14900, annual: 142900 }, business: { monthly: 59900, annual: 574900 } };
  return prices[plan]?.[billing] || 0;
}
async function authRequest(path, options = {}) {
  const response = await fetch(`${AUTH_CONFIG.supabaseUrl}${path}`, { ...options, headers: { apikey: AUTH_CONFIG.supabasePublishableKey, 'content-type': 'application/json', ...(options.headers || {}) } });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.msg || payload.error_description || payload.message || 'Authentification impossible.');
  return payload;
}
async function refreshAuth(session) { return authRequest('/auth/v1/token?grant_type=refresh_token', { method: 'POST', body: JSON.stringify({ refresh_token: session.refresh_token }) }); }
async function hydrateAuth() {
  const hash = new URLSearchParams(window.location.hash.replace(/^#/, ''));
  let session = normalizeAuthSession(authSession());
  if (hash.get('access_token')) { session = { access_token: hash.get('access_token'), refresh_token: hash.get('refresh_token'), expires_at: Math.floor(Date.now() / 1000) + Number(hash.get('expires_in') || 3600) }; history.replaceState({}, '', window.location.pathname + window.location.search); }
  if (session?.access_token && Number(session.expires_at || 0) < Math.floor(Date.now() / 1000) + 60) { try { session = normalizeAuthSession(await refreshAuth(session)); } catch { session = null; clearAuthSession(); } }
  if (!session?.access_token) { state.authUser = null; state.sessionId = ''; state.view = 'marketing'; render(); return; }
  try {
    const user = await authRequest('/auth/v1/user', { headers: authHeaders(session.access_token) });
    storeAuthSession(normalizeAuthSession({ ...session, user })); state.authUser = user; state.sessionId = user.id; state.view = 'app'; await syncEntitlement(false); const pendingPlan = state.pendingCheckoutPlan; state.checkoutPlan = pendingPlan || null; state.pendingCheckoutPlan = null; if (pendingPlan) { state.checkoutLoading = true; await beginCheckout(); return; }
  } catch { clearAuthSession(); state.authUser = null; state.sessionId = ''; state.view = 'marketing'; }
  render();
}

