function brand(html) { return html.replaceAll('rowz<span>.ai</span>', 'Huggy').replaceAll('rowz.ai', 'Huggy').replaceAll('Rowz', 'Huggy').replaceAll('rowz.local', 'huggy.local'); }
function render() { app.innerHTML = brand(state.view === 'marketing' ? landingMinimal() : dashboard() + (state.modal ? modal() : '')); }
async function startGeneration() {
  const prompt = (state.prompt || state.editPrompt || '').trim();
  if (!prompt || state.generating) return;
  if (!state.authUser) { state.modal = 'auth'; state.authMode = 'login'; render(); return; }
  if (state.generationCount >= state.generationLimit) { state.modal = 'paywall'; render(); return; }
  const currentFile = state.files.find(file => file.id === state.current) || null;
  const editing = Boolean(currentFile && state.editPrompt.trim());
  const baseWorkbook = editing ? currentFile.workbook : null;
  state.generating = true; state.progress = 0; state.error = ''; state.notice = ''; render();
  try {
    const response = await fetch('/api/generate', { method: 'POST', headers: { Accept: 'text/event-stream', 'Content-Type': 'application/json', ...authHeaders() }, body: JSON.stringify({ prompt, fileName: state.attachedFile?.name || '', fileText: state.attachedFile?.text || '', baseWorkbook }) });
    if (!response.ok) { const payload = await response.json().catch(() => ({})); const error = new Error(payload.error || 'La génération a échoué.'); error.status = response.status; throw error; }
    if (!response.body) throw new Error('Le flux de progression est indisponible.');
    const reader = response.body.getReader(); const decoder = new TextDecoder(); let buffer = ''; let payload = null;
    const consume = async block => { let event = 'message'; let data = ''; for (const line of block.split(/\r?\n/)) { if (line.startsWith('event:')) event = line.slice(6).trim(); if (line.startsWith('data:')) data += line.slice(5).trim(); } if (!data) return; const parsed = JSON.parse(data); if (event === 'stage') { const nextProgress = Math.max(state.progress, Math.min(4, Number(parsed.stage || 1) - 1)); if (nextProgress !== state.progress || Number(parsed.stage) === 1) { state.progress = nextProgress; render(); await new Promise(resolve => setTimeout(resolve, 450)); } } if (event === 'complete') payload = parsed; if (event === 'error') { const error = new Error(parsed.error || 'La génération a échoué.'); error.status = parsed.status; throw error; } };
    while (true) { const { value, done } = await reader.read(); buffer += decoder.decode(value || new Uint8Array(), { stream: !done }); const chunks = buffer.split(/\r?\n\r?\n/); buffer = chunks.pop() || ''; for (const chunk of chunks) await consume(chunk); if (done) break; }
    if (buffer.trim()) await consume(buffer);
    if (!payload) throw new Error('La génération n’a pas renvoyé de résultat.');
    state.progress = 5; render();
    await new Promise(resolve => setTimeout(resolve, 260));
    const id = editing ? currentFile.id : crypto.randomUUID();
    const title = payload.workbook?.title || 'classeur-ia';
    const nextVersion = editing ? Number(currentFile.version || 1) + 1 : 1;
    const versionEntry = { version: nextVersion, prompt, workbook: payload.workbook, createdAt: new Date().toISOString() };
    const file = editing ? { ...currentFile, prompt, version: nextVersion, workbook: payload.workbook, history: [...(currentFile.history || []), versionEntry] } : { id, name: `${title.toLowerCase().replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '') || 'classeur-ia'}.xlsx`, prompt, version: 1, workbook: payload.workbook, history: [versionEntry] };
    state.sheet = workbookSheets(file)[0]?.id || '';
    trackMeta('HuggyGeneration', { plan: payload.account?.plan || state.plan, has_attachment: Boolean(state.attachedFile) }, true);
    state.files = editing ? state.files.map(item => item.id === id ? file : item) : [...state.files.filter(f => f.id !== id), file]; state.current = id; state.plan = payload.account?.plan || state.plan; state.generationLimit = payload.account?.generationLimit || state.generationLimit; state.generationCount = payload.account?.used ?? (state.generationCount + 1); state.trialUsed = state.generationCount >= state.generationLimit; state.generating = false; state.prompt = ''; state.editPrompt = ''; state.attachedFile = null; state.notice = editing ? `Version ${nextVersion} enregistrée. Tu peux continuer à la modifier.` : 'Classeur généré et validé. Tu peux le prévisualiser, le modifier ou le télécharger.'; save(); render();
  } catch (error) {
    state.generating = false; state.error = error.message || 'Une erreur est survenue.'; if (error.status === 429) state.modal = 'paywall'; render();
  }
}

async function syncEntitlement(showCheckoutNotice = false) {
  if (!state.authUser) return false;
  try {
    const response = await fetch('/api/account', { headers: { accept: 'application/json', ...authHeaders() } });
    if (!response.ok) return false;
    const account = await response.json();
    state.plan = account.plan || 'free'; state.generationLimit = account.generationLimit || 1; state.generationCount = account.used || 0; state.trialUsed = state.generationCount >= state.generationLimit;
    if (showCheckoutNotice) {
      state.notice = account.status === 'active' ? `Paiement confirmé : le plan ${account.planName} est actif.` : 'Paiement reçu. L’activation automatique est en cours.';
      if (account.status === 'active' && sessionStorage.getItem('huggy-purchase-tracked') !== '1') {
        trackMeta('Purchase', { content_name: account.plan || state.plan, value: pixelPlanValue(account.plan || state.plan, account.billingCycle || state.billing), currency: 'XOF' });
        sessionStorage.setItem('huggy-purchase-tracked', '1');
      }
    }
    save(); render();
    return account.status === 'active';
  } catch { return false; }
}

app.addEventListener('input', e => { if (e.target.matches('[data-role="search"]')) { state.search = e.target.value; render(); } if (e.target.matches('[data-role="prompt"]')) state.prompt = e.target.value; if (e.target.matches('[data-role="edit-prompt"]')) state.editPrompt = e.target.value; });
app.addEventListener('change', async e => { if (!e.target.matches('[data-role="file-input"]') || !e.target.files?.[0]) return; const file = e.target.files[0]; const allowed = /\.(xlsx|xls|csv)$/i.test(file.name); if (!allowed) { state.error = 'Formats acceptés : .xlsx, .xls ou .csv.'; render(); return; } if (file.size > 5 * 1024 * 1024) { state.error = 'Le fichier doit faire moins de 5 Mo.'; render(); return; } let text = ''; if (/\.csv$/i.test(file.name)) text = (await file.text()).slice(0, 12000); state.attachedFile = { name: file.name, size: file.size, type: file.type, text }; if (!state.prompt) state.prompt = `Analyse et transforme le fichier ${file.name}`; state.error = ''; render(); });
async function beginAuth() { const authMode = state.authMode; const value = role => document.querySelector(`[data-role="${role}"]`)?.value.trim() || ''; const email = value('auth-email').toLowerCase(); const password = document.querySelector('[data-role="auth-password"]')?.value || ''; const firstName = value('auth-first-name'); const lastName = value('auth-last-name'); const phone = value('auth-phone'); const countryCode = value('auth-country').toUpperCase() || 'CI'; state.authLoading = true; state.authError = ''; state.authMessage = ''; render(); try { const payload = authMode === 'signup' ? await authRequest('/auth/v1/signup', { method: 'POST', body: JSON.stringify({ email, password, options: { email_redirect_to: window.location.origin + '/', data: { first_name: firstName, last_name: lastName, phone, country_code: countryCode } } }) }) : await authRequest('/auth/v1/token?grant_type=password', { method: 'POST', body: JSON.stringify({ email, password }) }); if (!payload.access_token) { state.authLoading = false; state.authMessage = 'Compte créé. Vérifie ton email pour confirmer ton adresse, puis connecte-toi.'; render(); return; } const session = normalizeAuthSession(payload); storeAuthSession(session); state.authUser = session.user; state.sessionId = session.user.id; state.view = 'app'; if (authMode === 'signup') trackMeta('CompleteRegistration', { status: 'completed', method: 'email' }); const pendingPlan = state.pendingCheckoutPlan; state.checkoutPlan = pendingPlan || null; state.pendingCheckoutPlan = null; state.modal = null; state.authLoading = false; await syncEntitlement(false); if (pendingPlan) { state.checkoutLoading = true; await beginCheckout(); } else render(); } catch (error) { state.authLoading = false; state.authError = error.message || 'Authentification impossible.'; render(); } }
async function signOut() { const session = authSession(); if (session?.access_token) await authRequest('/auth/v1/logout', { method: 'POST', headers: authHeaders(session.access_token) }).catch(() => {}); clearAuthSession(); state.authUser = null; state.sessionId = ''; state.view = 'marketing'; state.modal = null; state.menu = false; state.files = []; state.current = null; state.plan = 'free'; state.generationCount = 0; state.generationLimit = 1; save(); render(); }
async function saveProfile() { const value = role => document.querySelector(`[data-role="${role}"]`)?.value.trim() || ''; const firstName = value('profile-first-name'); const lastName = value('profile-last-name'); const phone = value('profile-phone'); const countryCode = value('profile-country').toUpperCase() || 'CI'; if (!firstName || !lastName || phone.replace(/\D/g, '').length < 6 || !/^[A-Z]{2}$/.test(countryCode)) { state.error = 'Renseigne un prénom, un nom, un téléphone et un code pays valide.'; render(); return; } try { const session = authSession(); const current = state.authUser?.user_metadata || {}; const user = await authRequest('/auth/v1/user', { method: 'PUT', headers: authHeaders(session?.access_token), body: JSON.stringify({ data: { ...current, first_name: firstName, last_name: lastName, phone, country_code: countryCode } }) }); state.authUser = user; storeAuthSession(normalizeAuthSession({ ...session, user })); state.accountEdit = null; state.notice = 'Profil enregistré. Les prochains paiements ouvriront directement le checkout Chariow.'; state.error = ''; render(); } catch (error) { state.error = error.message || 'Impossible d’enregistrer le profil.'; render(); } }
function signInWithGoogle() { trackMeta('Login', { method: 'google' }); const redirectTo = `${window.location.origin}/`; const authorize = new URL('/auth/v1/authorize', AUTH_CONFIG.supabaseUrl); authorize.searchParams.set('provider', 'google'); authorize.searchParams.set('redirect_to', redirectTo); window.location.assign(authorize.toString()); }
app.addEventListener('click', e => { const el = e.target.closest('[data-action="google-login"]'); if (el) { e.stopImmediatePropagation(); signInWithGoogle(); } });
app.addEventListener('click', e => { const el = e.target.closest('[data-action]'); if (!el) return; if (el.dataset.action === 'login') trackMeta('HuggyCtaClick', { placement: el.classList.contains('minimal-cta') ? 'landing' : 'navigation' }, true); if (el.dataset.action === 'plans' && el.dataset.plan) trackMeta('ViewContent', { content_name: el.dataset.plan, content_type: 'subscription' }); });
function checkoutDetailsFromUser() { return { email: state.authUser?.email || '' }; }
function startCheckoutForPlan(plan) { state.checkoutPlan = plan; state.error = ''; state.checkoutLoading = true; state.modal = null; render(); beginCheckout(); }
async function beginCheckout() { if (!state.authUser || !state.checkoutPlan) return; state.checkoutLoading = true; state.error = ''; render(); try { const response = await fetch('/api/checkout', { method: 'POST', headers: { 'Content-Type': 'application/json', ...authHeaders() }, body: JSON.stringify({ plan: state.checkoutPlan, billing: state.billing }) }); const payload = await response.json(); if (!response.ok || !payload.checkoutUrl) { const error = new Error(payload.error || 'Le paiement n’est pas disponible.'); error.status = response.status; throw error; } trackMeta('InitiateCheckout', { content_name: state.checkoutPlan, value: pixelPlanValue(state.checkoutPlan, state.billing), currency: 'XOF' }); window.location.href = payload.checkoutUrl; } catch (error) { state.checkoutLoading = false; state.error = error.message || 'Impossible de préparer le paiement.'; if (error.status === 400 && /profil/i.test(error.message || '')) { state.modal = 'account'; state.accountTab = 'profile'; state.accountEdit = 'profile'; } else state.modal = 'paywall'; render(); } }
app.addEventListener('click', e => { const el = e.target.closest('[data-action]'); if (el?.dataset.action === 'save-profile') { e.stopImmediatePropagation(); saveProfile(); } });
app.addEventListener('click', e => { const el = e.target.closest('[data-action]'); if (!el) return; const a = el.dataset.action; if (a === 'dismiss-promo') state.promo = false; if (a === 'marketing') { state.view = 'marketing'; state.menu = false; } if (a === 'login') { state.view = 'app'; state.menu = false; } if (a === 'language') { state.lang = state.lang === 'fr' ? 'en' : 'fr'; } if (a === 'account') state.menu = !state.menu; if (a === 'account-manage') { state.menu = false; state.modal = 'account'; state.accountTab = 'profile'; state.accountEdit = null; } if (a === 'account-tab') { state.accountTab = el.dataset.tab; state.accountEdit = null; } if (a === 'update-profile') state.accountEdit = 'profile'; if (a === 'update-password') state.accountEdit = 'password'; if (a === 'cancel-account-edit') state.accountEdit = null; if (a === 'email-menu') state.emailMenu = !state.emailMenu; if (a === 'logout') { state.view = 'marketing'; state.menu = false; } if (a === 'collapse') state.collapsed = !state.collapsed; if (a === 'new-file') { state.current = null; state.prompt = ''; state.editPrompt = ''; state.attachedFile = null; state.modal = null; } if (a === 'plans') state.modal = 'paywall'; if (a === 'billing') state.billing = el.dataset.billing || 'monthly'; if (a === 'start-checkout') { state.checkoutPlan = el.dataset.plan; state.checkoutLoading = false; state.error = ''; } if (a === 'back-plans') { state.checkoutPlan = null; state.checkoutLoading = false; state.error = ''; } if (a === 'checkout-submit') { beginCheckout(); return; } if (a === 'open-file') state.current = el.dataset.id; if (a === 'quick') { if (state.current) state.editPrompt = el.dataset.prompt; else state.prompt = el.dataset.prompt; } if (a === 'attach') { const input = el.parentElement?.parentElement?.querySelector('[data-role="file-input"]') || app.querySelector('[data-role="file-input"]'); input?.click(); return; } if (a === 'remove-attachment') state.attachedFile = null; if (a === 'dismiss-error') state.error = ''; if (a === 'dismiss-notice') state.notice = ''; if (a === 'generate') { startGeneration(); return; } if (a === 'preview') { const file = state.files.find(item => item.id === state.current) || state.files[0]; state.modal = 'preview'; state.sheet = workbookSheets(file)[0]?.id || ''; } if (a === 'download') { if (state.plan === 'free') state.modal = 'paywall'; else downloadWorkbook(); } if (a === 'continue') { state.editPrompt = ''; } if (a === 'close-modal') state.modal = null; if (a === 'sheet') state.sheet = el.dataset.sheet; save(); render(); });
app.addEventListener('click', e => { const el = e.target.closest('[data-action]'); if (!el) return; const a = el.dataset.action; if (a === 'login') { state.view = 'marketing'; state.modal = 'auth'; state.authMode = 'login'; state.authError = ''; state.authMessage = ''; } if (a === 'plans') { if (el.dataset.plan) state.pendingCheckoutPlan = el.dataset.plan; if (!state.authUser) { state.modal = 'auth'; state.authMode = 'login'; state.authError = ''; state.authMessage = ''; } else if (el.dataset.plan) { state.checkoutPlan = el.dataset.plan; state.modal = 'paywall'; } } if (a === 'auth-switch') { state.authMode = state.authMode === 'login' ? 'signup' : 'login'; state.authError = ''; state.authMessage = ''; } if (a === 'logout') { signOut(); return; } render(); });
app.addEventListener('click', e => { const el = e.target.closest('[data-action]'); if (!el) return; if (el.dataset.action === 'start-checkout') startCheckoutForPlan(el.dataset.plan); if (el.dataset.action === 'plans' && el.dataset.plan && state.authUser) startCheckoutForPlan(el.dataset.plan); });
